namespace AvaloniaDCT.Models;

// Immutable snapshot of "who is logged in" for this process.
// record = value-like type with UserId, UserName, Password generated by the compiler.
// Password is the typed login secret. In hardened mode it is also the SQLCipher key
// cached so later connections do not ask the user again.
public sealed record UserSession(int UserId, string UserName, string Password);
